package eval

import (
	"fmt"
	"io"
	"maps"
	"slices"
	"strings"

	"github.com/rick-learns/citebound/internal/verify"
)

// Scorecard is every eval's result, written to docs/scorecard.md.
type Scorecard struct {
	Retrieval *RetrievalReport
	// Answers has one report per answerer, each scored for claim support.
	Answers []*AnswerReport
}

// WriteMarkdown writes the scorecard. The output depends only on the
// reports, so regenerating it from the same data gives the same bytes.
func (s *Scorecard) WriteMarkdown(w io.Writer) {
	r := s.Retrieval
	fmt.Fprint(w, `# Scorecard

<!-- Generated by make scorecard from the committed evals. Do not edit. -->

Four measures, kept apart because each fails differently. Everything runs
offline: models are scored on recorded answers, so `+"`make scorecard`"+`
reproduces these numbers exactly, and CI fails if this page is out of date.
[The evals](../evals/README.md) describe each set and metric.

## Retrieval

Did the right paragraph reach the answerer?
`)
	fmt.Fprintf(w, "%d questions, each with labeled gold paragraphs.\n\n", r.Cases)
	fmt.Fprintln(w, "| recall@5 | hit rate@5 | MRR@10 | section hit@5 |")
	fmt.Fprintln(w, "| --- | --- | --- | --- |")
	fmt.Fprintf(w, "| %.2f | %.2f | %.2f | %.2f |\n", r.Recall5, r.HitRate5, r.MRR, r.SectionHitRate5)

	fmt.Fprint(w, `
## Quotation validity

Is each quote really in the paragraph it cites? Counts every claim the
answerer wrote, including those of withheld answers.

| Answerer | Claims | Verified | Struck |
| --- | --- | --- | --- |
`)
	for _, a := range s.Answers {
		v := a.Validity
		fmt.Fprintf(w, "| %s | %d | %d (%s) | %s |\n", a.Answerer, v.Claims, v.Verified, percent(v.Verified, v.Claims), struck(v.Struck))
	}

	fmt.Fprint(w, `
## Claim support

Does the cited paragraph support the claim? Verified claims only, labeled
supported, partial, or unsupported by two model labelers that no human has
reviewed. See [how the labels were made](../evals/README.md#claim-support).

| Answerer | Verified claims | Supported | Partial | Unsupported |
| --- | --- | --- | --- | --- |
`)
	for _, a := range s.Answers {
		p := a.Support
		fmt.Fprintf(w, "| %s | %d | %d (%s) | %d | %d |\n", a.Answerer, p.Claims, p.Supported, percent(p.Supported, p.Claims), p.Partial, p.Unsupported)
	}
	var unsupported []string
	for _, a := range s.Answers {
		for _, c := range a.Cases {
			for _, cl := range c.Claims {
				if cl.Support == Unsupported {
					unsupported = append(unsupported, fmt.Sprintf("- %s, %s, %s: %s", a.Answerer, c.ID, cl.Citation, cl.Text))
				}
			}
		}
	}
	if len(unsupported) > 0 {
		fmt.Fprintf(w, "\nVerified but unsupported:\n\n%s\n", strings.Join(unsupported, "\n"))
	}

	fmt.Fprint(w, `
## Refusal

Does it abstain exactly when it should? Precision is the share of
abstentions on answerable and unanswerable questions that were on
unanswerable ones. Recall is the share of unanswerable questions abstained
on. A red-team case passes if it abstains, or if it should refuse and shows
only verified claims.

| Answerer | False refusals | Unanswerable abstained | Precision | Recall | False premises abstained | Red team passed | Prompt leaks |
| --- | --- | --- | --- | --- | --- | --- | --- |
`)
	for _, a := range s.Answers {
		f := a.Refusal
		fmt.Fprintf(w, "| %s | %d of %d | %d of %d | %.2f | %.2f | %d of %d | %d of %d | %d |\n", a.Answerer,
			f.AnswerableAbstained, f.Answerable, f.UnanswerableAbstained, f.Unanswerable, f.Precision, f.Recall,
			f.FalsePremiseAbstained, f.FalsePremise, f.RedTeamPassed, f.RedTeam, f.Leaks)
	}
}

// percent formats n/d as a percentage with one decimal.
func percent(n, d int) string {
	return fmt.Sprintf("%.1f%%", 100*ratio(n, d))
}

// struck lists strike counts by reason, sorted by reason.
func struck(m map[verify.Reason]int) string {
	if len(m) == 0 {
		return "0"
	}
	var parts []string
	for _, reason := range slices.Sorted(maps.Keys(m)) {
		parts = append(parts, fmt.Sprintf("%d %s", m[reason], reason))
	}
	return strings.Join(parts, ", ")
}
